<?php
 function array_add (&$a, $b) { foreach ($b as $v) { $a[] = $v; } } function array_merge_recursive_overwritten ($a, $b) { if (!is_array($a) or !is_array($b)) { return $b; } foreach ($b as $k => $v) { $a[$k] = array_merge_recursive_overwritten($a[$k] ?? null, $v); } return $a; } function isUndefinedArrayValue ($array, $index, $default = null) { return (isset($array[$index]) || (is_array($array) && array_key_exists($index, $array))) ? $array[$index] : $default; } function isNullArrayValue ($array, $index, $default = null) { return isset($array[$index]) ? $array[$index] : $default; } function isEmptyArrayValue ($array, $index, $default = null) { return empty($array[$index]) ? $default : $array[$index]; } function arrayToObject ($array, $class) { $object = new $class; foreach($array as $k => $v) { $object->{$k} = $v; } return $object; } function arrayFindObject ($arr, $nameKey, $valueKey) { if (!is_array($arr)) { $arr = [$arr]; } foreach ($arr as $item) { if ((!is_object($item) && $item == $valueKey) || (is_object($item) && property_exists($item, $nameKey) && $item->{$nameKey} == $valueKey) ) { return $item; } if (is_array($item) && array_key_exists($nameKey, $item) && $item[$nameKey] == $valueKey) { return (object)$item; } } return null; } 